using System.Collections.Generic; using System.Threading; using System.Threading.Tasks; using Hakchii.Next.Core.Device; using Xunit;
namespace Hakchii.Next.Core.Tests; public class DeviceInfoTests { [Fact] public async Task ReadsHakchiDeviceFacts(){var t=new T();var i=await new DeviceInfoService(t).ReadAsync(CancellationToken.None);Assert.Equal("ABC123",i.HardwareId);Assert.Equal("nes-usa",i.SystemCode);Assert.Equal("/var/lib/hakchi/games",i.GameStoragePath);Assert.Equal(5,t.Commands.Count);} private sealed class T:IDeviceCommandTransport{public bool IsOnline=>true;public List<string> Commands{get;}=new();public Task ConnectAsync(CancellationToken c)=>Task.CompletedTask;public Task DisconnectAsync(CancellationToken c)=>Task.CompletedTask;public Task<string> ExecuteAsync(string x,CancellationToken c){Commands.Add(x);if(x=="hakchi hwid")return Task.FromResult("ABC 123");if(x.Contains("sftype"))return Task.FromResult("nes-usa");if(x.Contains("findGameSyncStorage"))return Task.FromResult("/var/lib/hakchi/games");if(x.Contains("gamepath"))return Task.FromResult("/usr/share/games");return Task.FromResult("/rootfs");}} }
